    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your account security settings.</p>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-row" style="margin-top: 1.5rem;">
                <label class="toggle-label">
                    <span>Two-Factor Authentication</span>
                    <span class="toggle-description">
                        @if (_twoFactorEnabled)
                        {
                            <span class="status-indicator enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-indicator disabled">● Disabled</span>
                        }
                    </span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted" style="margin-top: 1rem; font-size: 0.875rem;">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            <!-- Active Sessions -->
            <h4 class="subsection-title" style="margin-top: 2rem;">Active Sessions</h4>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge current-badge">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-sm btn-danger" @onclick="() => RequestRevoke(session)">
                                                Revoke
