    background: #333;
    color: #e0e0e0;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%);
    color: #212529;
}

/* Preview font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

