    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-header {
    margin-bottom: 0.5rem;
}

.preview-compact .preview-text {
    margin-bottom: 0.5rem;
    line-height: 1.3;
}

