toolArgs.file_text:
@page "/settings"
@using sv_200fb41a5ee542078f0c4f1d6ec01112.Models
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Sidebar Navigation -->
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <!-- Main Content -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            <!-- Toast Message -->
            @if (_showToast)
            {
                <div class="toast-message @(_toastType)">
                    @_toastMessage
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

<!-- Revoke Session Confirmation Dialog -->
@if (_showRevokeDialog)
{
    <div class="dialog-overlay" @onclick="CancelRevoke">
        <div class="dialog" @onclick:stopPropagation="true">
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
            <p class="dialog-warning">This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
            </div>
        </div>
    </div>
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast state
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile state
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["announcements", "random", "off-topic", "watercooler", "design-review"];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        _loading = true;
        try
        {
            switch (_activeSection)
            {
                case "Profile":
                    var profile = await SettingsService.GetProfileAsync();
                    _savedProfile = profile;
                    _displayName = profile.DisplayName;
                    _email = profile.Email;
                    _avatarUrl = profile.AvatarUrl;
                    _bio = profile.Bio;
                    break;

                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    _emailNotifications = prefs.EmailNotifications;
                    _pushNotifications = prefs.PushNotifications;
                    _weeklyDigest = prefs.WeeklyDigest;
                    _mutedChannels = new HashSet<string>(prefs.MutedChannels);
                    break;

                case "Security":
                    _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
                    _changePasswordExpanded = false;
                    _currentPassword = "";
                    _newPassword = "";
                    _confirmPassword = "";
                    break;

                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    _theme = appearance.Theme;
                    _fontSize = appearance.FontSize;
                    _language = appearance.Language;
                    _compactMode = appearance.CompactMode;
                    break;
            }
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SetActiveSection(string section)
    {
        if (_activeSection == section) return;
        _activeSection = section;
        _showToast = false;
        await LoadSectionData();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private async Task ShowToast(string message, string type = "success")
    {
        _toastMessage = message;
        _toastType = type;
        _showToast = true;
        StateHasChanged();
        await Task.Delay(3000);
        _showToast = false;
        StateHasChanged();
    }

    // ── Profile ──

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your public profile information.</p>

            <div class="form-group avatar-group">
                <label>Avatar</label>
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                </div>
                <div class="avatar-url">
                    <span class="text-muted">URL: @_avatarUrl</span>
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _avatarUrl = _savedProfile.AvatarUrl;
        _bio = _savedProfile.Bio;
    }

    // ── Notifications ──

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label class="toggle-label">
                        <span>Email Notifications</span>
                        <span class="toggle-description">Receive notifications via email</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <label class="toggle-label">
                        <span>Push Notifications</span>
                        <span class="toggle-description">Receive push notifications in browser</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <label class="toggle-label">
                        <span>Weekly Digest</span>
                        <span class="toggle-description">Get a weekly summary of activity</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            <p class="text-muted">Muted channels will not send you notifications.</p>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@ch</span>
                        @if (_mutedChannels.Contains(ch))
                        {
                            <span class="badge muted-badge">Muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ──

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your account security settings.</p>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-row" style="margin-top: 1.5rem;">
                <label class="toggle-label">
                    <span>Two-Factor Authentication</span>
                    <span class="toggle-description">
                        @if (_twoFactorEnabled)
                        {
                            <span class="status-indicator enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-indicator disabled">● Disabled</span>
                        }
                    </span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted" style="margin-top: 1rem; font-size: 0.875rem;">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            <!-- Active Sessions -->
            <h4 class="subsection-title" style="margin-top: 2rem;">Active Sessions</h4>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge current-badge">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-sm btn-danger" @onclick="() => RequestRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            await ShowToast("All password fields are required.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked successfully.");
    }

    // ── Appearance ──

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label class="group-label">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        var t = theme;
                        <label class="radio-option @(_theme == t ? "selected" : "")">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_theme == t)"
                                   @onchange="() => _theme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="group-label">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        var s = size;
                        <label class="radio-option @(_fontSize == s ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_fontSize == s)"
                                   @onchange="() => _fontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language" class="group-label">Language</label>
                <select id="language" class="form-control" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <span class="toggle-description">Reduce spacing and padding throughout the UI</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <h4 class="subsection-title" style="margin-top: 2rem;">Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">
                    <strong>Sample Header</strong>
                    <span class="preview-badge">Badge</span>
                </div>
                <p class="preview-text">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-actions">
                    <button class="preview-btn primary">Primary Action</button>
                    <button class="preview-btn secondary">Secondary Action</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }
}

