+                            <span class="status-indicator enabled">● Enabled</span>
+                        }
+                        else
+                        {
+                            <span class="status-indicator disabled">● Disabled</span>
+                        }
+                    </span>
+                </label>
+                <label class="switch">
+                    <input type="checkbox" @bind="_twoFactorEnabled" />
+                    <span class="slider"></span>
+                </label>
+            </div>
+
+            @if (_securitySettings?.LastPasswordChange is not null)
+            {
+                <p class="text-muted" style="margin-top: 1rem; font-size: 0.875rem;">
+                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
+                </p>
+            }
+
+            <!-- Active Sessions -->
+            <h4 class="subsection-title" style="margin-top: 2rem;">Active Sessions</h4>
+            @if (_securitySettings?.Sessions is { Count: > 0 })
+            {
+                <div class="sessions-table-wrapper">
+                    <table class="sessions-table">
+                        <thead>
+                            <tr>
+                                <th>Device</th>
+                                <th>Location</th>
+                                <th>Last Active</th>
+                                <th></th>
+                            </tr>
+                        </thead>
+                        <tbody>
+                            @foreach (var session in _securitySettings.Sessions)
+                            {
+                                var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
+                                <tr>
+                                    <td>
+                                        @session.Device
+                                        @if (isCurrentSession)
+                                        {
+                                            <span class="badge current-badge">Current</span>
+                                        }
+                                    </td>
+                                    <td>@session.Location</td>
+                                    <td>@FormatLastActive(session.LastActive)</td>
+                                    <td>
+                                        @if (!isCurrentSession)
+                                        {
+                                            <button class="btn btn-sm btn-danger" @onclick="() => RequestRevoke(session)">
+                                                Revoke
+                                            </button>
+                                        }
+                                    </td>
+                                </tr>
+                            }
+                        </tbody>
+                    </table>
+                </div>
+            }
+        </section>
+    };
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+
+    private async Task UpdatePassword()
+    {
+        if (string.IsNullOrWhiteSpace(_currentPassword) ||
+            string.IsNullOrWhiteSpace(_newPassword) ||
+            string.IsNullOrWhiteSpace(_confirmPassword))
+        {
+            await ShowToast("All password fields are required.", "error");
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            await ShowToast("New passwords do not match.", "error");
+            return;
+        }
+
+        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        _currentPassword = "";
+        _newPassword = "";
+        _confirmPassword = "";
+        _changePasswordExpanded = false;
+        await ShowToast("Password updated successfully!");
+    }
+
+    private void RequestRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+        _showRevokeDialog = true;
+    }
+
+    private void CancelRevoke()
+    {
+        _showRevokeDialog = false;
+        _sessionToRevoke = null;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (_sessionToRevoke is not null)
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        }
+        _showRevokeDialog = false;
+        _sessionToRevoke = null;
+        await ShowToast("Session revoked successfully.");
+    }
+
